import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import ReviewSection from './ReviewSection';

const MovieList = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGenre, setSelectedGenre] = useState('');
  const [language, setLanguage] = useState('EN');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const navigate = useNavigate();

  const moviePosters = {
    'The Matrix': 'https://image.tmdb.org/t/p/original/ulf1aY9LXciRX2IpnJksCDJOWvp.jpg',
    'Inception': 'https://image.tmdb.org/t/p/original/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg',
    'The Dark Knight': 'https://tse2.mm.bing.net/th/id/OIP.pzHzXKTcOWnvKPz1Tfyp0QHaLH?rs=1&pid=ImgDetMain&o=7&rm=3',
    'Pulp Fiction': 'https://tse2.mm.bing.net/th/id/OIP.IhmaVUWP5Apwt4QLEZmTywHaJQ?rs=1&pid=ImgDetMain&o=7&rm=3',
    'Forrest Gump': 'https://media-cache.cinematerial.com/p/500x/4ovpiklv/forrest-gump-movie-poster.jpg?v=1560360911',
    'Avatar: The Way of Water': 'https://tse4.mm.bing.net/th/id/OIP._rp3eKfy9c5k30t9z0YrJgHaKx?rs=1&pid=ImgDetMain&o=7&rm=3',
    'Oppenheimer': 'https://tse4.mm.bing.net/th/id/OIP.Ew4Zjg1klAQO_NQRbG0dJAHaK9?rs=1&pid=ImgDetMain&o=7&rm=3',
    'Barbie': 'https://th.bing.com/th/id/R.f656e5de3aa09f0dba4d4a6708f927e1?rik=ItNMfwGDqd5lmA&riu=http%3a%2f%2fmoviepostersaustralia.com%2fcdn%2fshop%2ffiles%2fBarbie_2023_Advance1SheetMargotRobbieRyanGoslingWMfront.webp%3fv%3d1712636654&ehk=%2fBVhPlllmAaAPHCd3l%2f7%2fCntG3rtJD01xSQFEJEmNis%3d&risl=&pid=ImgRaw&r=0',
    'Spider-Man: No Way Home': 'https://mir-s3-cdn-cf.behance.net/project_modules/1400/c590d5131586213.6197b316721dd.png',
    'The Avengers': 'https://tse4.mm.bing.net/th/id/OIP.zNDZbJ1vd_HW_D_3F1zaYgHaLH?rs=1&pid=ImgDetMain&o=7&rm=3',
    'Dune: Part Two': 'https://media-cache.cinematerial.com/p/500x/4ovpiklv/dune-part-two-movie-poster.jpg?v=1560360911',
    'Top Gun: Maverick': 'https://media-cache.cinematerial.com/p/500x/4ovpiklv/top-gun-maverick-movie-poster.jpg?v=1560360911',
    'The Flash': 'https://media-cache.cinematerial.com/p/500x/4ovpiklv/the-flash-movie-poster.jpg?v=1560360911'
  };

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/movies');
      const moviesWithPosters = response.data.map(movie => ({
        ...movie,
        posterUrl: moviePosters[movie.title] || null
      }));
      setMovies(moviesWithPosters);
    } catch (error) {
      console.error('Error fetching movies:', error);
    } finally {
      setLoading(false);
    }
  };

  const genres = [...new Set(movies.map(movie => movie.genre))];

  const filteredMovies = movies.filter(movie => {
    const matchesSearch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesGenre = !selectedGenre || movie.genre === selectedGenre;
    return matchesSearch && matchesGenre;
  });

  const handleBookMovie = (movie) => {
    // Navigate to booking page
    window.location.href = `/booking/${movie.movieId}`;
  };

  if (loading) {
    return (
      <div className="container">
        <div style={{ textAlign: 'center', padding: '8rem' }}>
          <div className="loading-spinner">
            <div style={{ 
              width: '60px', 
              height: '60px', 
              border: '4px solid var(--primary-gold)', 
              borderTop: '4px solid transparent', 
              borderRadius: '50%',
              animation: 'spin 1s linear infinite',
              margin: '0 auto'
            }}></div>
            <h2 style={{ marginTop: '2rem', color: 'var(--text-secondary)' }}>Loading amazing movies...</h2>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      {/* Hero Section */}
      <div className="hero">
        <div className="hero-content">
          <h1 className="hero-title">
            {language === 'EN' ? 'CINEMA EXPERIENCE' : 'सिनेमा अनुभव'}
          </h1>
          <p className="hero-subtitle">
            {language === 'EN' 
              ? 'Book tickets for the latest blockbuster movies' 
              : 'नवीनतम ब्लॉकबस्टर फिल्मों के लिए टिकट बुक करें'}
          </p>
        </div>
      </div>

      {/* Language Toggle */}
      <div className="language-toggle">
        <button 
          className={`language-btn ${language === 'EN' ? 'active' : ''}`}
          onClick={() => setLanguage('EN')}
        >
          EN
        </button>
        <button 
          className={`language-btn ${language === 'HI' ? 'active' : ''}`}
          onClick={() => setLanguage('HI')}
        >
          हिं
        </button>
      </div>

      <div className="container">
        <div className="page-header">
          <h1 className="page-title">
            {language === 'EN' ? 'Now Showing' : 'अब प्रदर्शित'}
          </h1>
          <p className="page-subtitle">
            {language === 'EN' 
              ? 'Book tickets for the latest movies' 
              : 'नवीनतम फिल्मों के लिए टिकट बुक करें'}
          </p>
        </div>

        <div className="search-bar">
          <div className="search-container">
            <input
              type="text"
              placeholder={language === 'EN' ? 'Search movies...' : 'फिल्म खोजें...'}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="form-input search-input"
            />

            <select
              value={selectedGenre}
              onChange={(e) => setSelectedGenre(e.target.value)}
              className="form-input filter-select"
            >
              <option value="">{language === 'EN' ? 'All Genres' : 'सभी शैलियां'}</option>
              {genres.map(genre => (
                <option key={genre} value={genre}>{genre}</option>
              ))}
            </select>
          </div>
        </div>

        {filteredMovies.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '4rem' }}>
            <h2 style={{ color: 'var(--text-secondary)' }}>
              {language === 'EN' ? 'No movies found' : 'कोई फिल्म नहीं मिली'}
            </h2>
            <p style={{ color: 'var(--text-secondary)', marginTop: '1rem' }}>
              {language === 'EN' 
                ? 'Try adjusting your search or filter criteria' 
                : 'अपनी खोज या फिल्टर समायोजित करें'}
            </p>
          </div>
        ) : (
          <div className="movie-grid">
            {filteredMovies.map(movie => (
              <div key={movie.movieId} className="movie-card" onClick={() => handleBookMovie(movie)}>
                <div className="movie-poster">
                  {movie.posterUrl ? (
                    <img src={movie.posterUrl} alt={movie.title} />
                  ) : (
                    <span style={{ fontSize: '4rem' }}>🎬</span>
                  )}
                  <div className="movie-badge">
                    {language === 'EN' ? 'NEW' : 'नया'}
                  </div>
                  <div className="movie-rating">
                    ⭐ {movie.rating || '8.5'}
                  </div>
                </div>
                <div className="movie-info">
                  <h3 className="movie-title">{movie.title}</h3>
                  <div className="movie-meta">
                    <span className="movie-genre">{movie.genre}</span>
                  </div>
                  <div className="movie-footer">
                    <span className="movie-price">${movie.price}</span>
                    <span className="movie-duration">{movie.durationMinutes}min</span>
                  </div>
                  <button 
                    className="btn btn-primary"
                    style={{ marginTop: '16px', width: '100%' }}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleBookMovie(movie);
                    }}
                  >
                    {language === 'EN' ? 'Book Now' : 'अभी बुक करें'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <style jsx>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default MovieList;
